-- SPUN Learning Hub — migrasi 2: panel admin & materi di database.
-- Jalankan SEKALI di Supabase SQL Editor setelah migrasi 1 (20261117000000_learning_hub_init.sql).
-- Aman dijalankan ulang: setiap langkah memeriksa kondisi sebelum mengubah.

-- 1) Role & status akun
alter table public.users add column if not exists role text not null default 'learner';
alter table public.users add column if not exists status text not null default 'active';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'users_role_check') then
    alter table public.users add constraint users_role_check check (role in ('learner', 'admin'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'users_status_check') then
    alter table public.users add constraint users_status_check check (status in ('active', 'disabled'));
  end if;
end $$;

-- 2) Materi: draft (sedang diedit admin) dan published (yang dilihat peserta)
create table if not exists public.content_items (
  kind text not null check (kind in ('course', 'quiz', 'article')),
  id text not null check (id ~ '^[a-z0-9]([a-z0-9-]{0,58}[a-z0-9])?$'),
  draft jsonb not null,
  published jsonb,
  sort_order integer not null default 0,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users (id) on delete set null,
  published_at timestamptz,
  published_revision integer,
  primary key (kind, id)
);
alter table public.content_items enable row level security;
revoke all on table public.content_items from anon, authenticated;

-- 3) Progres modul memakai ID modul (bukan nomor urut), supaya aman saat modul disisipkan/diurutkan ulang
do $$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'lesson_progress' and column_name = 'lesson_index') then
    alter table public.lesson_progress add column if not exists lesson_id text;
    update public.lesson_progress set lesson_id = course_id || '-m' || (lesson_index + 1) where lesson_id is null;
    alter table public.lesson_progress alter column lesson_id set not null;
    alter table public.lesson_progress drop constraint if exists lesson_progress_pkey;
    alter table public.lesson_progress add primary key (user_id, course_id, lesson_id);
    alter table public.lesson_progress drop column lesson_index;
  end if;
end $$;

-- 4) Isi awal materi (dari katalog contoh). Tidak menimpa materi yang sudah ada.
insert into public.content_items (kind, id, draft, published, sort_order, published_at, published_revision) values
  ('course', 'cx', $json${"title":"Delivering Exceptional Customer Experience","category":"Customer Experience","description":"Bangun pengalaman pelanggan yang berkesan, dari percakapan pertama hingga solusi terakhir.","color":"peach","level":"Fundamental","art":"conversation","lessons":[{"id":"cx-m1","title":"Memahami customer experience","duration":8,"intro":"Pengalaman pelanggan dibentuk oleh setiap interaksi, termasuk ketika pelanggan sedang menunggu jawaban.","sections":[{"heading":"Lihat perjalanan secara utuh","html":"<p>Customer experience mencakup sebelum, selama, dan setelah layanan. Gunakan sudut pandang pelanggan untuk menemukan momen yang membingungkan atau membuat mereka perlu bertanya ulang.</p>"},{"heading":"Kenali kebutuhan di balik pertanyaan","html":"<p>Pertanyaan tentang status dapat menunjukkan kebutuhan akan kepastian. Selain memberikan status terakhir yang terverifikasi, jelaskan langkah berikutnya dan kapan pembaruan akan diberikan.</p>"},{"heading":"Latihan singkat","html":"<p>Pilih satu percakapan yang pernah kamu tangani. Catat kebutuhan pelanggan, respons yang diberikan, dan satu hal yang dapat membuat pengalaman itu lebih mudah.</p>"}]},{"id":"cx-m2","title":"Mengenal customer journey","duration":7,"intro":"Petakan perjalanan pelanggan untuk memahami titik kontak dan hambatan yang mereka alami.","sections":[{"heading":"Mulai dari tujuan pelanggan","html":"<p>Tuliskan hasil yang ingin dicapai pelanggan, kemudian urutkan tahap yang mereka lalui. Catat pertanyaan, emosi, dan informasi yang dibutuhkan pada setiap tahap.</p>"},{"heading":"Temukan titik friksi","html":"<p>Perhatikan informasi yang harus disampaikan berulang, perpindahan tim tanpa konteks, dan langkah yang tidak jelas. Tentukan satu perbaikan kecil yang bisa diuji.</p>"}]},{"id":"cx-m3","title":"Empati dalam setiap percakapan","duration":10,"intro":"Empati membantu pelanggan merasa didengar. Mulailah dengan memahami konteks sebelum menawarkan solusi.","sections":[{"heading":"Dengarkan dan validasi","html":"<p>Baca percakapan secara utuh. Akui dampak situasinya secara spesifik tanpa membuat asumsi tentang perasaan pelanggan. Contoh: “Saya memahami kepastian jadwal ini penting untuk persiapan Kakak.”</p>"},{"heading":"Jelaskan tindakan yang nyata","html":"<p>Sampaikan apa yang akan diperiksa, siapa yang akan menindaklanjuti, dan kapan kamu akan memberi kabar. Hindari janji hasil yang berada di luar kendali tim.</p>"},{"heading":"Coba terapkan","html":"<p>Pelanggan sudah bertanya dua kali tentang status. Susun respons yang berisi pengakuan atas situasi, status yang telah diverifikasi, serta langkah dan waktu pembaruan berikutnya.</p>"}]},{"id":"cx-m4","title":"Mengelola ekspektasi pelanggan","duration":10,"intro":"Ekspektasi yang jelas mengurangi kebingungan dan membantu membangun kepercayaan.","sections":[{"heading":"Pisahkan fakta dan estimasi","html":"<p>Sampaikan apa yang sudah terkonfirmasi dan apa yang masih berupa perkiraan. Jangan mengubah estimasi menjadi janji pasti.</p>"},{"heading":"Beri pembaruan yang berguna","html":"<p>Saat belum ada perubahan, jelaskan apa yang masih ditunggu dan tindakan yang sedang dilakukan. Sepakati waktu pembaruan yang realistis sesuai prosedur tim.</p>"}]},{"id":"cx-m5","title":"Menutup percakapan dengan baik","duration":10,"intro":"Penutupan yang baik memastikan pelanggan mengetahui hasil dan langkah berikutnya.","sections":[{"heading":"Rangkum hasil","html":"<p>Sebutkan solusi atau status akhir secara ringkas. Pastikan pertanyaan utama terjawab dan tanyakan apakah masih ada hal yang perlu dibantu.</p>"},{"heading":"Catat untuk tindak lanjut","html":"<p>Dokumentasikan inti kendala, tindakan, komitmen pembaruan, dan penanggung jawab. Gunakan prosedur internal yang berlaku sebagai acuan.</p>"}]}]}$json$::jsonb, $json${"title":"Delivering Exceptional Customer Experience","category":"Customer Experience","description":"Bangun pengalaman pelanggan yang berkesan, dari percakapan pertama hingga solusi terakhi