  ('course', 'onboarding', $json${"title":"Welcome to SPUN: Start Your Journey","category":"Onboarding","description":"Kenali ruang belajarmu dan siapkan kebiasaan belajar yang mendukung pekerjaan.","color":"blue","level":"Fundamental","art":"journey","lessons":[{"id":"onboarding-m1","title":"Mengenal Learning Hub","duration":8,"intro":"Learning Hub adalah ruang untuk menemukan materi, berlatih, dan menyimpan pengetahuan.","sections":[{"heading":"Mulai dari Dashboard","html":"<p>Lihat progres course, lanjutkan pembelajaran, dan temukan kuis yang tersedia.</p>"},{"heading":"Temukan materi","html":"<p>Gunakan pencarian atau kategori untuk memilih course dan artikel yang sesuai kebutuhan.</p>"}]},{"id":"onboarding-m2","title":"Merencanakan pembelajaran","duration":9,"intro":"Tujuan kecil yang konsisten membantu membangun kebiasaan belajar.","sections":[{"heading":"Pilih satu kebutuhan","html":"<p>Pilih keterampilan yang sering digunakan dalam pekerjaan. Tentukan waktu belajar yang realistis setiap minggu.</p>"},{"heading":"Terapkan hasil belajar","html":"<p>Setelah menyelesaikan materi, tulis satu tindakan yang ingin kamu coba dalam pekerjaan.</p>"}]},{"id":"onboarding-m3","title":"Belajar bersama tim","duration":8,"intro":"Diskusi membantu menghubungkan materi dengan situasi nyata.","sections":[{"heading":"Bagikan pembelajaran","html":"<p>Bawa satu contoh dan satu pertanyaan ke sesi diskusi tim.</p>"},{"heading":"Pastikan acuan terbaru","html":"<p>Untuk kebijakan dan prosedur operasional, gunakan dokumen internal yang telah disetujui dan diperbarui oleh pemilik proses.</p>"}]}]}$json$::jsonb, $json${"title":"Welcome to SPUN: Start Your Journey","category":"Onboarding","description":"Kenali ruang belajarmu dan siapkan kebiasaan belajar yang mendukung pekerjaan.","color":"blue","level":"Fundamental","art":"journey","lessons":[{"id":"onboarding-m1","title":"Mengenal Learning Hub","duration":8,"intro":"Learning Hub adalah ruang untuk menemukan materi, berlatih, dan menyim