  ('course', 'documentation', $json${"title":"Case Documentation Essentials","category":"Service Quality","description":"Tulis catatan kasus yang jelas agar setiap tindak lanjut berjalan lebih mudah.","color":"sand","level":"Fundamental","art":"documents","lessons":[{"id":"documentation-m1","title":"Catatan yang berguna","duration":10,"intro":"Catatan kasus membantu rekan tim memahami konteks tanpa meminta pelanggan mengulang.","sections":[{"heading":"Struktur sederhana","html":"<p>Catat kebutuhan, fakta, tindakan yang sudah dilakukan, status, dan langkah berikutnya.</p>"},{"heading":"Gunakan bahasa netral","html":"<p>Bedakan fakta dengan dugaan. Hindari penilaian pribadi tentang pelanggan.</p>"}]},{"id":"documentation-m2","title":"Handover yang jelas","duration":10,"intro":"Handover yang baik membuat kepemilikan tindak lanjut tetap jelas.","sections":[{"heading":"Sertakan konteks utama","html":"<p>Sampaikan ringkasan kendala, bukti yang relevan, upaya penyelesaian, dan dukungan yang diperlukan.</p>"},{"heading":"Pastikan penerima","html":"<p>Gunakan jalur internal yang berlaku dan konfirmasi bahwa pemilik tindak lanjut telah ditentukan.</p>"}]},{"id":"documentation-m3","title":"Pemeriksaan sebelum menutup kasus","duration":10,"intro":"Luangkan waktu untuk mengecek kelengkapan catatan.","sections":[{"heading":"Tiga pertanyaan pemeriksaan","html":"<p>Apakah statusnya jelas? Apakah pelanggan mengetahui langkah berikutnya? Apakah ada komitmen yang masih harus ditindaklanjuti?</p>"},{"heading":"Jaga informasi pelanggan","html":"<p>Gunakan sistem yang disetujui perusahaan dan simpan hanya informasi yang relevan sesuai kebijakan internal.</p>"}]}]}$json$::jsonb, $json${"title":"Case Documentation Essentials","category":"Service Quality","description":"Tulis catatan kasus yang jelas agar setiap tindak lanjut berjalan lebih mudah.","color":"sand","level":"Fundamental","art":"documents","lessons":[{"id":"documentation-m1","title":"Catatan yang berguna","duration":10,"intro":"Catatan kasus membantu rekan tim memahami konteks tanpa meminta pelanggan mengulang.","sections":[{"heading":"Struktur sederhana","html":"<p>Catat kebutuhan, fakta, tindakan yang sudah dilakukan, status, dan langkah berikutnya.</p>"},{"heading":"Gunakan bahasa netral","html":"<p>Bedakan fakta dengan dugaan. Hindari penilaian pribadi tentang pelanggan.</p>"}]},{"id":"documentation-m2","title":"Handover yang jelas","duration":10,"intro":"Handover yang baik membuat kepemilikan tindak lanjut tetap jelas.","sections":[{"heading":"Sertakan konteks utama","html":"<p>Sampaikan ringkasan kendala, bukti yang relevan, upaya penyelesaian, dan dukungan yang diperlukan.</p>"},{"heading":"Pastikan penerima","html":"<p>Gunakan jalur internal yang berlaku dan konfirmasi bahwa pemilik tindak lanjut telah ditentukan.</p>"}]},{"id":"documentation-m3","title":"Pemeriksaan sebelum menutup kasus","duration":10,"intro":"Luangkan waktu untuk mengecek kelengkapan catatan.","sections":[{"heading":"Tiga pertanyaan pemeriksaan","html":"<p>Apakah statusnya jelas? Apakah pelanggan mengetahui langkah berikutnya? Apakah ada komitmen yang masih harus ditindaklanjuti?</p>"},{"heading":"Jaga informasi pelanggan","html":"<p>Gunakan sistem yang disetujui perusahaan dan simpan hanya informasi yang relevan sesuai kebijakan internal.</p>"}]}],"label":"SERVICE QUALITY","minutes":30}$json$::jsonb, 50, now(), 1),
  ('course', 'ownership', $json${"title":"Taking Ownership of Every Case","category":"Customer Experience","description":"Bangun rasa tanggung jawab dan tindak lanjut yang dapat diandalkan.","color":"pink","level":"Intermediate","art":"ownership","lessons":[{"id":"ownership-m1","title":"Memahami ownership","duration":10,"intro":"Ownership berarti memastikan setiap kasus memiliki langkah berikutnya yang jelas.","sections":[{"heading":"Ambil tanggung jawab atas tindak lanjut","html":"<p>Kamu tidak selalu bisa menyelesaikan semuanya sendiri, tetapi bisa memastikan konteks diteruskan dan pelanggan menerima pembaruan.</p>"},{"heading":"Hindari janji berlebihan","html":"<p>Komitmenkan tindakan yang berada dalam kendalimu. Konfirmasi hasil sebelum menyampaikannya.</p>"}]},{"id":"ownership-m2","title":"Kolaborasi lintas tim","duration":10,"intro":"Kolaborasi yang baik dimulai dengan informasi yang lengkap.","sections":[{"heading":"Jelaskan kebutuhan bantuan","html":"<p>Sampaikan pertanyaan atau keputusan yang dibutuhkan secara spesifik.</p>"},{"heading":"Catat hasil koordinasi","html":"<p>Dokumentasikan keputusan dan penanggung jawab agar tindak lanjut tidak terlewat.</p>"}]},{"id":"ownership-m3","title":"Follow-up yang konsisten","duration":10,"intro":"Pembaruan yang konsisten membantu menjaga kepercayaan.","sections":[{"heading":"Buat pengingat","html":"<p>Catat komitmen pembaruan pada sistem kerja tim yang disetujui.</p>"},{"heading":"Tutup lingkaran komunikasi","html":"<p>Pastikan pelanggan mengetahui hasil akhir atau alasan mengapa tindak lanjut masih diperlukan.</p>"}]}]}$json$::jsonb, $json${"title":"Taking Ownership of Every Case","category":"Customer Experience","description":"Bangun rasa tanggung jawab dan tindak lanjut yang dapat diandalkan.","color":"pink","level":"Intermediate","art":"ownership","lessons":[{"id":"ownership-m1","title":"Memahami ownership","duration":10,"intro":"Ownership berarti memastikan setiap kasus memiliki langkah berikutnya yang jelas.","sections":[{"heading":"Ambil tanggung jawab atas tindak lanjut","html":"<p>Kamu tidak selalu bisa menyelesaikan semuanya sendiri, tetapi bisa memastikan konteks diteruskan dan pelanggan menerima pembaruan.</p>"},{"heading":"Hindari janji berlebihan","html":"<p>Komitmenkan tindakan yang berada dalam kendalimu. Konfirmasi hasil sebelum menyampaikannya.</p>"}]},{"id":"ownership-m2","title":"Kolaborasi lintas tim","duration":10,"intro":"Kolaborasi yang baik dimulai dengan informasi yang lengkap.","sections":[{"heading":"Jelaskan kebutuhan bantuan","html":"<p>Sampaikan pertanyaan atau keputusan yang dibutuhkan secara spesifik.</p>"},{"heading":"Catat hasil koordinasi","html":"<p>Dokumentasikan keputusan dan penanggung jawab agar tindak lanjut tidak terlewat.</p>"}]},{"id":"ownership-m3","title":"Follow-up yang konsisten","duration":10,"intro":"Pembaruan yang konsisten membantu menjaga kepercayaan.","sections":[{"heading":"Buat pengingat","html":"<p>Catat komitmen pembaruan pada sistem kerja tim yang disetujui.</p>"},{"heading":"Tutup lingkaran komunikasi","html":"<p>Pastikan pelanggan mengetahui hasil akhir atau alasan mengapa tindak lanjut masih diperlukan.</p>"}]}],"label":"CUSTOMER EXPERIENCE","minutes":30}$json$::jsonb, 60, now(), 1),
  ('quiz', 'cx-quiz', $json${"title":"Customer Experience Fundamentals","category":"Customer Experience","description":"Seberapa baik kamu memahami pengalaman pelanggan? Saatnya uji pemahamanmu.","color":"peach","minutes":8,"course":"cx","questions":[{"q":"Pelanggan sudah dua kali menanyakan status. Respons mana yang paling tepat?","options":["Meminta pelanggan menunggu tanpa penjelasan","Mengakui situasi, memberi status terverifikasi, dan menjelaskan waktu pembaruan","Menjanjikan hasil pasti hari ini","Mengirim jawaban otomatis yang sama"],"answer":1,"why":"Pengakuan, informasi yang akurat, dan rencana pembaruan membantu memberikan kepastian tanpa menjanjikan hasil di luar kendali."},{"q":"Customer journey mencakup interaksi pada tahap apa?","options":["Hanya saat pelanggan menyampaikan komplain","Hanya setelah transaksi","Sebelum, selama, dan setelah menggunakan layanan","Hanya saat menghubungi agent"],"answer":2,"why":"Pengalaman pelanggan terbentuk dari seluruh titik kontak, bukan hanya percakapan dengan tim support."},{"q":"Bagaimana sebaiknya menyampaikan estimasi?","options":["Sebagai janji pasti","Dengan menyebutkan bahwa itu perkiraan dan menjelaskan faktor yang relevan","Tidak perlu disampaikan","Dengan memilih waktu tercepat tanpa verifikasi"],"answer":1,"why":"Estimasi perlu dibedakan dari hasil yang sudah terkonfirmasi agar ekspektasi pelanggan tetap realistis."},{"q":"Apa langkah penting sebelum menutup percakapan?","options":["Langsung mengakhiri chat","Mengirim promosi tambahan","Merangkum hasil dan memastikan langkah berikutnya jelas","Meminta pelanggan mengulang seluruh masalah"],"answer":2,"why":"Ringkasan dan langkah berikutnya membantu memastikan pelanggan memahami hasil dan tindak lanjut."},{"q":"Manakah contoh empati yang spesifik?","options":["“Semua pelanggan mengalami hal sama.”","“Saya memahami kepastian jadwal ini penting untuk persiapan Kakak.”","“Tidak perlu khawatir, pasti selesai.”","“Itu bukan tanggung jawab saya.”"],"answer":1,"why":"Empati mengakui konteks pelanggan secara spesifik, tanpa mengecilkan masalah atau membuat janji yang belum terverifikasi."}]}$json$::jsonb, $json${"title":"Customer Experience Fundamentals","category":"Customer Experience","description":"Seberapa baik kamu memahami pengalaman pelanggan? Saatnya uji pemahamanmu.","color":"peach","minutes":8,"course":"cx","questions":[{"q":"Pelanggan sudah dua kali menanyakan status. Respons mana yang paling tepat?","options":["Meminta pelanggan menunggu tanpa penjelasan","Mengakui situasi, memberi status terverifikasi, dan menjelaskan waktu pembaruan","Menjanjikan hasil pasti hari ini","Mengirim jawaban otomatis yang sama"],"answer":1,"why":"Pengakuan, informasi yang akurat, dan rencana pembaruan membantu memberikan kepastian tanpa menjanjikan hasil di luar kendali."},{"q":"Customer journey mencakup interaksi pada tahap apa?","options":["Hanya saat pelanggan menyampaikan komplain","Hanya setelah transaksi","Sebelum, selama, dan setelah menggunakan layanan","Hanya saat menghubungi agent"],"answer":2,"why":"Pengalaman pelanggan terbentuk dari seluruh titik kontak, bukan hanya percakapan dengan tim support."},{"q":"Bagaimana sebaiknya menyampaikan estimasi?","options":["Sebagai janji pasti","Dengan menyebutkan bahwa itu perkiraan dan menjelaskan faktor yang relevan","Tidak perlu disampaikan","Dengan memilih waktu tercepat tanpa verifikasi"],"answer":1,"why":"Estimasi perlu dibedakan dari hasil yang sudah terkonfirmasi agar ekspektasi pelanggan tetap realistis."},{"q":"Apa langkah penting sebelum menutup percakapan?","options":["Langsung mengakhiri chat","Mengirim promosi tambahan","Merangkum hasil dan memastikan langkah berikutnya jelas","Meminta pelanggan mengulang seluruh masalah"],"answer":2,"why":"Ringkasan dan langkah berikutnya membantu memastikan pelanggan memahami hasil dan tindak lanjut."},{"q":"Manakah contoh empati yang spesifik?","options":["“Semua pelanggan mengalami hal sama.”","“Saya memahami kepastian jadwal ini penting untuk persiapan Kakak.”","“Tidak perlu khawatir, pasti selesai.”","“Itu bukan tanggung jawab saya.”"],"answer":1,"why":"Empati mengakui konteks pelanggan secara spesifik, tanpa mengecilkan masalah atau membuat janji yang belum terverifikasi."}]}$json$::jsonb, 10, now(), 1),
  ('quiz', 'communication-quiz', $json${"title":"The Art of Active Listening","category":"Communication","description":"Latih kemampuan mendengarkan dan memilih respons yang tepat.","color":"sage","minutes":6,"course":"communication","questions":[{"q":"Apa tujuan utama active listening?","options":["Menjawab secepat mungkin","Memahami pesan dan kebutuhan sebelum merespons","Mengarahkan semua percakapan ke template","Mempersingkat setiap jawaban"],"answer":1,"why":"Active listening membantu memahami kebutuhan secara akurat sebelum memilih respons."},{"q":"Kapan pertanyaan klarifikasi berguna?","options":["Saat ada informasi penting yang belum jelas","Setiap kali pelanggan mengetik","Setelah percakapan ditutup","Hanya untuk memperpanjang chat"],"answer":0,"why":"Klarifikasi digunakan untuk memastikan detail yang diperlukan, dengan memanfaatkan informasi yang sudah tersedia."},{"q":"Pelanggan menyampaikan instruksi membingungkan. Apa tindakan terbaik?","options":["Mengirim instruksi yang sama","Mengatakan instruksinya sudah jelas","Mengakui kendala lalu menyederhanakan langkah","Meminta pelanggan membaca ulang tanpa bantuan"],"answer":2,"why":"Mengakui kendala dan menyesuaikan penjelasan membantu pelanggan melanjutkan proses."},{"q":"Bagaimana cara memeriksa pemahaman?","options":["Membuat asumsi sendiri","Merangkum kebutuhan dan meminta konfirmasi bila perlu","Mengganti topik","Meminta semua dokumen lagi"],"answer":1,"why":"Parafrase dan konfirmasi mengurangi kesalahpahaman tanpa meminta pelanggan mengulang seluruh cerita."},{"q":"Bahasa layanan yang efektif sebaiknya…","options":["Penuh istilah internal","Panjang dan rumit","Sederhana, jelas, dan ramah","Selalu sama untuk semua kondisi"],"answer":2,"why":"Bahasa yang sederhana dan sesuai konteks memudahkan pelanggan memahami informasi dan tindakan berikutnya."}]}$json$::jsonb, $json${"title":"The Art of Active Listening","category":"Communication","description":"Latih kemampuan mendengarkan dan memilih respons yang tepat.","color":"sage","minutes":6,"course":"communication","questions":[{"q":"Apa tujuan utama active listening?","options":["Menjawab secepat mungkin","Memahami pesan dan kebutuhan sebelum merespons","Mengarahkan semua percakapan ke template","Mempersingkat setiap jawaban"],"answer":1,"why":"Active listening membantu memahami kebutuhan secara akurat sebelum memilih respons."},{"q":"Kapan pertanyaan klarifikasi berguna?","options":["Saat ada informasi penting yang belum jelas","Setiap kali pelanggan mengetik","Setelah percakapan ditutup","Hanya untuk memperpanjang chat"],"answer":0,"why":"Klarifikasi digunakan untuk memastikan detail yang diperlukan, dengan memanfaatkan informasi yang sudah tersedia."},{"q":"Pelanggan menyampaikan instruksi membingungkan. Apa tindakan terbaik?","options":["Mengirim instruksi yang sama","Mengatakan instruksinya sudah jelas","Mengakui kendala lalu menyederhanakan langkah","Meminta pelanggan membaca ulang tanpa bantuan"],"answer":2,"why":"Mengakui kendala dan menyesuaikan penjelasan membantu pelanggan melanjutkan proses."},{"q":"Bagaimana cara memeriksa pemahaman?","options":["Membuat asumsi sendiri","Merangkum kebutuhan dan meminta konfirmasi bila perlu","Mengganti topik","Meminta semua dokumen lagi"],"answer":1,"why":"Parafrase dan konfirmasi mengurangi kesalahpahaman tanpa meminta pelanggan mengulang seluruh cerita."},{"q":"Bahasa layanan yang efektif sebaiknya…","options":["Penuh istilah internal","Panjang dan rumit","Sederhana, jelas, dan ramah","Selalu sama untuk semua kondisi"],"answer":2,"why":"Bahasa yang sederhana dan sesuai konteks memudahkan pelanggan memahami informasi dan tindakan berikutnya."}]}$json$::jsonb, 20, now(), 1),
  ('quiz', 'quality-quiz', $json${"title":"Service Quality Essentials","category":"Service Quality","description":"Gunakan insight QA untuk memilih langkah perbaikan yang tepat.","color":"lavender","minutes":7,"course":"service","questions":[{"q":"Feedback QA yang berguna didasarkan pada…","options":["Kesan pribadi","Contoh perilaku yang dapat diamati","Perbandingan personal antarrekan","Satu angka tanpa penjelasan"],"answer":1,"why":"Contoh spesifik membuat feedback lebih jelas, adil, dan dapat ditindaklanjuti."},{"q":"Sebelum membuat improvement plan, apa yang perlu dipahami?","options":["Akar masalah dan konteksnya","Siapa yang harus disalahkan","Cara menaikkan angka tanpa perubahan","Template paling panjang"],"answer":0,"why":"Tindakan perbaikan perlu sesuai dengan penyebab, misalnya pengetahuan, akses informasi, atau kejelasan proses."},{"q":"Target coaching yang baik bersifat…","options":["Abstrak tanpa batas waktu","Sama untuk semua orang","Spesifik, dapat diamati, dan memiliki waktu evaluasi","Hanya berfokus pada niat"],"answer":2,"why":"Target perilaku yang jelas membuat kemajuan dapat diperiksa bersama."},{"q":"Catatan kasus sebaiknya mencakup…","options":["Opini tentang pelanggan","Masalah, fakta, tindakan, status, dan langkah berikutnya","Hanya nama pelanggan","Hanya tanggal percakapan"],"answer":1,"why":"Struktur ini membantu rekan tim memahami kasus dan melanjutkan penanganan."},{"q":"Setelah coaching, langkah berikutnya adalah…","options":["Menganggap masalah sudah selesai","Melakukan evaluasi sampel baru dan memberi feedback","Menghapus catatan QA","Mengubah semua standar sekaligus"],"answer":1,"why":"Tindak lanjut memeriksa penerapan hasil coaching dan membantu menjaga perubahan yang konsisten."}]}$json$::jsonb, $json${"title":"Service Quality Essentials","category":"Service Quality","description":"Gunakan insight QA untuk memilih langkah perbaikan yang tepat.","color":"lavender","minutes":7,"course":"service","questions":[{"q":"Feedback QA yang berguna didasarkan pada…","options":["Kesan pribadi","Contoh perilaku yang dapat diamati","Perbandingan personal antarrekan","Satu angka tanpa penjelasan"],"answer":1,"why":"Contoh spesifik membuat feedback lebih jelas, adil, dan dapat ditindaklanjuti."},{"q":"Sebelum membuat improvement plan, apa yang perlu dipahami?","options":["Akar masalah dan konteksnya","Siapa yang harus disalahkan","Cara menaikkan angka tanpa perubahan","Template paling panjang"],"answer":0,"why":"Tindakan perbaikan perlu sesuai dengan penyebab, misalnya pengetahuan, akses informasi, atau kejelasan proses."},{"q":"Target coaching yang baik bersifat…","options":["Abstrak tanpa batas waktu","Sama untuk semua orang","Spesifik, dapat diamati, dan memiliki waktu evaluasi","Hanya berfokus pada niat"],"answer":2,"why":"Target perilaku yang jelas membuat kemajuan dapat diperiksa bersama."},{"q":"Catatan kasus sebaiknya mencakup…","options":["Opini tentang pelanggan","Masalah, fakta, tindakan, status, dan langkah berikutnya","Hanya nama pelanggan","Hanya tanggal percakapan"],"answer":1,"why":"Struktur ini membantu rekan tim memahami kasus dan melanjutkan penanganan."},{"q":"Setelah coaching, langkah berikutnya adalah…","options":["Menganggap masalah sudah selesai","Melakukan evaluasi sampel baru dan memberi feedback","Menghapus catatan QA","Mengubah semua standar sekaligus"],"answer":1,"why":"Tindak lanjut memeriksa penerapan hasil coaching dan membantu menjaga perubahan yang konsisten."}]}$json$::jsonb, 30, now(), 1),
  ('article', 'empathy', $json${"title":"Empati bukan sekadar “mohon maaf”","category":"Customer Experience","description":"Cara membangun koneksi yang lebih tulus dalam setiap percakapan dengan pelanggan.","color":"peach","art":"conversation","minutes":5,"featured":true,"sections":[{"heading":"Memahami sebelum merespons","html":"<p>Permintaan maaf dapat membantu, tetapi empati menjadi lebih bermakna ketika respons menunjukkan bahwa kita memahami situasi pelanggan. Perhatikan kebutuhan yang disampaikan, dampaknya, dan informasi apa yang masih mereka tunggu.</p>"},{"heading":"Gunakan pengakuan yang spesifik","html":"<p>Alih-alih hanya menulis “mohon maaf atas ketidaknyamanannya”, hubungkan respons dengan konteks. Contoh: “Saya memahami bahwa kepastian jadwal ini penting untuk persiapan Kakak. Saya akan memeriksa status terakhir dan menginformasikan langkah berikutnya.”</p>"},{"heading":"Lanjutkan dengan tindakan","html":"<p>Empati perlu diikuti tindakan yang nyata. Sampaikan status yang sudah terverifikasi dan kapan pembaruan berikutnya akan diberikan. Hindari menjanjikan hasil yang tidak berada dalam kendalimu.</p>"},{"heading":"Coba dalam percakapan berikutnya","html":"<p>Sebelum mengirim respons, periksa tiga hal: apakah konteks pelanggan sudah diakui, apakah informasinya akurat, dan apakah langkah berikutnya jelas?</p>"}]}$json$::jsonb, $json${"title":"Empati bukan sekadar “mohon maaf”","category":"Customer Experience","description":"Cara membangun koneksi yang lebih tulus dalam setiap percakapan dengan pelanggan.","color":"peach","art":"conversation","minutes":5,"featured":true,"sections":[{"heading":"Memahami sebelum merespons","html":"<p>Permintaan maaf dapat membantu, tetapi empati menjadi lebih bermakna ketika respons menunjukkan bahwa kita memahami situasi pelanggan. Perhatikan kebutuhan yang disampaikan, dampaknya, dan informasi apa yang masih mereka tunggu.</p>"},{"heading":"Gunakan pengakuan yang spesifik","html":"<p>Alih-alih hanya menulis “mohon maaf atas ketidaknyamanannya”, hubungkan respons dengan konteks. Contoh: “Saya memahami bahwa kepastian jadwal ini penting untuk persiapan Kakak. Saya akan memeriksa status terakhir dan menginformasikan langkah berikutnya.”</p>"},{"heading":"Lanjutkan dengan tindakan","html":"<p>Empati perlu diikuti tindakan yang nyata. Sampaikan status yang sudah terverifikasi dan kapan pembaruan berikutnya akan diberikan. Hindari menjanjikan hasil yang tidak berada dalam kendalimu.</p>"},{"heading":"Coba dalam percakapan berikutnya","html":"<p>Sebelum mengirim respons, periksa tiga hal: apakah konteks pelanggan sudah diakui, apakah informasinya akurat, dan apakah langkah berikutnya jelas?</p>"}]}$json$::jsonb, 10, now(), 1),
  ('article', 'handover', $json${"title":"Checklist handover: agar tidak ada cerita yang terulang","category":"Service Quality","description":"Lima hal sederhana yang perlu ada saat meneruskan kasus ke rekan tim.","color":"sand","art":"documents","minutes":4,"featured":false,"sections":[{"heading":"Mulai dari ringkasan","html":"<p>Tulis tujuan pelanggan dan kendala utama dalam beberapa kalimat. Gunakan bahasa netral dan hindari detail yang tidak relevan.</p>"},{"heading":"Catat tindakan yang sudah dilakukan","html":"<p>Sampaikan pemeriksaan, hasil koordinasi, serta informasi yang sudah diberikan kepada pelanggan. Ini membantu tim penerima menghindari pengulangan.</p>"},{"heading":"Buat tindak lanjut jelas","html":"<p>Cantumkan status saat ini, dukungan yang diperlukan, pemilik langkah berikutnya, dan komitmen waktu pembaruan. Sesuaikan jalur handover dengan prosedur internal yang berlaku.</p>"}]}$json$::jsonb, $json${"title":"Checklist handover: agar tidak ada cerita yang terulang","category":"Service Quality","description":"Lima hal sederhana yang perlu ada saat meneruskan kasus ke rekan tim.","color":"sand","art":"documents","minutes":4,"featured":false,"sections":[{"heading":"Mulai dari ringkasan","html":"<p>Tulis tujuan pelanggan dan kendala utama dalam beberapa kalimat. Gunakan bahasa netral dan hindari detail yang tidak relevan.</p>"},{"heading":"Catat tindakan yang sudah dilakukan","html":"<p>Sampaikan pemeriksaan, hasil koordinasi, serta informasi yang sudah diberikan kepada pelanggan. Ini membantu tim penerima menghindari pengulangan.</p>"},{"heading":"Buat tindak lanjut jelas","html":"<p>Cantumkan status saat ini, dukungan yang diperlukan, pemilik langkah berikutnya, dan komitmen waktu pembaruan. Sesuaikan jalur handover dengan prosedur internal yang berlaku.</p>"}]}$json$::jsonb, 20, now(), 1),
  ('article', 'feedback', $json${"title":"Dari feedback ke kebiasaan baru","category":"Learning & Growth","description":"Jadikan feedback sebagai langkah kecil yang bisa dipraktikkan setiap hari.","color":"sage","art":"growth","minutes":6,"featured":false,"sections":[{"heading":"Pilih satu hal untuk diperbaiki","html":"<p>Feedback akan lebih mudah diterapkan jika diterjemahkan menjadi satu tindakan yang spesifik. Gunakan contoh percakapan agar perubahan yang diinginkan jelas.</p>"},{"heading":"Buat ruang untuk berlatih","html":"<p>Lakukan role-play singkat atau susun ulang respons pada kasus sebelumnya. Diskusikan apa yang berubah dan mengapa respons itu lebih membantu.</p>"},{"heading":"Tinjau kemajuan bersama","html":"<p>Pada waktu evaluasi yang disepakati, lihat sampel baru. Akui perubahan yang sudah terlihat dan tentukan penyesuaian berikutnya.</p>"}]}$json$::jsonb, $json${"title":"Dari feedback ke kebiasaan baru","category":"Learning & Growth","description":"Jadikan feedback sebagai langkah kecil yang bisa dipraktikkan setiap hari.","color":"sage","art":"growth","minutes":6,"featured":false,"sections":[{"heading":"Pilih satu hal untuk diperbaiki","html":"<p>Feedback akan lebih mudah diterapkan jika diterjemahkan menjadi satu tindakan yang spesifik. Gunakan contoh percakapan agar perubahan yang diinginkan jelas.</p>"},{"heading":"Buat ruang untuk berlatih","html":"<p>Lakukan role-play singkat atau susun ulang respons pada kasus sebelumnya. Diskusikan apa yang berubah dan mengapa respons itu lebih membantu.</p>"},{"heading":"Tinjau kemajuan bersama","html":"<p>Pada waktu evaluasi yang disepakati, lihat sampel baru. Akui perubahan yang sudah terlihat dan tentukan penyesuaian berikutnya.</p>"}]}$json$::jsonb, 30, now(), 1),
  ('article', 'expectations', $json${"title":"Mengelola ekspektasi tanpa overpromise","category":"Communication","description":"Tetap membantu dan memberikan kepastian tanpa menjanjikan hal di luar kendali.","color":"blue","art":"journey","minutes":4,"featured":false,"sections":[{"heading":"Bedakan hasil dan tindakan","html":"<p>Kamu mungkin belum dapat memastikan hasil akhir, tetapi dapat menjelaskan pemeriksaan atau koordinasi yang akan dilakukan.</p>"},{"heading":"Gunakan bahasa yang terukur","html":"<p>Sebutkan mana fakta terkonfirmasi dan mana estimasi. Jika terdapat ketidakpastian, jelaskan dengan bahasa yang mudah dipahami.</p>"},{"heading":"Penuhi komitmen pembaruan","html":"<p>Catat janji pembaruan dan tindak lanjuti sesuai waktu yang disepakati. Jika hasil belum tersedia, informasikan status dan langkah yang masih berjalan.</p>"}]}$json$::jsonb, $json${"title":"Mengelola ekspektasi tanpa overpromise","category":"Communication","description":"Tetap membantu dan memberikan kepastian tanpa menjanjikan hal di luar kendali.","color":"blue","art":"journey","minutes":4,"featured":false,"sections":[{"heading":"Bedakan hasil dan tindakan","html":"<p>Kamu mungkin belum dapat memastikan hasil akhir, tetapi dapat menjelaskan pemeriksaan atau koordinasi yang akan dilakukan.</p>"},{"heading":"Gunakan bahasa yang terukur","html":"<p>Sebutkan mana fakta terkonfirmasi dan mana estimasi. Jika terdapat ketidakpastian, jelaskan dengan bahasa yang mudah dipahami.</p>"},{"heading":"Penuhi komitmen pembaruan","html":"<p>Catat janji pembaruan dan tindak lanjuti sesuai waktu yang disepakati. Jika hasil belum tersedia, informasikan status dan langkah yang masih berjalan.</p>"}]}$json$::jsonb, 40, now(), 1),
  ('article', 'knowledge', $json${"title":"Knowledge base yang benar-benar membantu","category":"Learning & Growth","description":"Temukan dan gunakan informasi dengan lebih cepat, tanpa kehilangan konteks.","color":"lavender","art":"quality","minutes":5,"featured":false,"sections":[{"heading":"Cari berdasarkan kebutuhan","html":"<p>Gunakan kata kunci yang menggambarkan kasus atau tujuan. Periksa apakah artikel membahas kondisi yang sama.</p>"},{"heading":"Periksa pemilik dan pembaruan","html":"<p>Untuk informasi operasional, pastikan dokumen memiliki pemilik proses dan pembaruan yang jelas. Jika ada konflik informasi, konfirmasi melalui jalur internal.</p>"},{"heading":"Berikan feedback","html":"<p>Catat pertanyaan yang belum terjawab dan bagian yang membingungkan. Masukan ini membantu pemilik materi meningkatkan kualitas knowledge base.</p>"}]}$json$::jsonb, $json${"title":"Knowledge base yang benar-benar membantu","category":"Learning & Growth","description":"Temukan dan gunakan informasi dengan lebih cepat, tanpa kehilangan konteks.","color":"lavender","art":"quality","minutes":5,"featured":false,"sections":[{"heading":"Cari berdasarkan kebutuhan","html":"<p>Gunakan kata kunci yang menggambarkan kasus atau tujuan. Periksa apakah artikel membahas kondisi yang sama.</p>"},{"heading":"Periksa pemilik dan pembaruan","html":"<p>Untuk informasi operasional, pastikan dokumen memiliki pemilik proses dan pembaruan yang jelas. Jika ada konflik informasi, konfirmasi melalui jalur internal.</p>"},{"heading":"Berikan feedback","html":"<p>Catat pertanyaan yang belum terjawab dan bagian yang membingungkan. Masukan ini membantu pemilik materi meningkatkan kualitas knowledge base.</p>"}]}$json$::jsonb, 50, now(), 1)
on conflict (kind, id) do nothing;

-- 5) Tempat gambar materi (publik untuk dibaca; unggah hanya lewat API admin)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('lms-media', 'lms-media', true, 5242880, array['image/png', 'image/jpeg', 'image/webp', 'image/gif'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- 6) Laporan ringkas (dibaca lewat SQL Editor; panel admin punya laporan sendiri)
drop view if exists public.learning_report;
create view public.learning_report with (security_invoker = true) as
select u.id as user_id, u.name, u.email, u.role, u.status,
  (select count(*) from public.enrollments e where e.user_id = u.id) as courses_enrolled,
  (select count(*) from public.lesson_progress p where p.user_id = u.id) as lessons_completed,
  (select count(distinct quiz_id) from public.quiz_attempts a where a.user_id = u.id) as quizzes_attempted,
  (select count(distinct quiz_id) from public.quiz_attempts a where a.user_id = u.id and a.score >= 80) as quizzes_passed,
  (select max(x) from (
     select max(completed_at) as x from public.lesson_progress p where p.user_id = u.id
     union all select max(created_at) from public.quiz_attempts a where a.user_id = u.id) s) as last_activity
from public.users u;
revoke all on public.learning_report from anon, authenticated;

-- 7) Jadikan akun Anda admin pertama: login sekali ke aplikasi, lalu jalankan (ganti emailnya):
-- update public.users set role = 'admin' where email = 'nama@spun.global';
